  List<Person> findByEmailUnknownAndLastname(EmailAddress emailAddress, String lastname); //プロパティ 'Unknown' を解決できません
  List<Person> findByAndLastname(EmailAddress emailAddress, String lastname); // プロパティ名が欠落しています

  List<Person> findDistinctPeopleByLastnameOrFirstname(String lastname, String firstname);
  List<Person> findPeopleDistinctByUnknownOrFirstname(String lastname, String firstname); // プロパティ 'Unknown' を解決できません

  List<Person> findByLastnameOrderByFirstnameAsc(String lastname);
  List<Person> findByLastnameOrderByUnknownDesc(String lastname);  // プロパティ 'Unknown' を解決できません
}' Inspection ID: SpringDataMethodInconsistencyInspection

