         @Gateway(
            requestChannel ="simpleBean",   // Bean は次の型のいずれかにする必要があります: org.springframework.integration.MessageChannel,org.springframework.messaging.MessageChannel
            replyChannel = "unknownChannel")   // チャンネルが見つかりません
         public void errors() {...}

         @Bean
